/** Source text is inserted with textContent only. No external assets or telemetry. */
export const INSPECTOR_PAGE = String.raw `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Recanta Inspector</title><style>
:root{color-scheme:light;--ink:#1e293b;--muted:#64748b;--line:#dbe3ec;--accent:#0f766e}*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:var(--ink);font:15px/1.55 system-ui,sans-serif}header{background:#fff;border-bottom:1px solid var(--line);padding:24px max(24px,calc((100vw - 1180px)/2))}h1{font-size:26px;margin:0}header p{margin:5px 0;color:var(--muted)}main{max-width:1228px;margin:auto;padding:24px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.field{display:grid;gap:5px;flex:1;min-width:170px}label{font-weight:600;font-size:13px}input,select,textarea,button{font:inherit;border:1px solid var(--line);border-radius:7px;padding:10px 12px}input,select,textarea{background:white;width:100%}button{cursor:pointer;background:white;color:var(--ink)}button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:disabled{opacity:.5;cursor:wait}.columns{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:20px;margin-top:20px}.panel,.card{background:white;border:1px solid var(--line);border-radius:10px;padding:18px;margin-bottom:14px}h2{font-size:18px;margin:0 0 12px}h3{font-size:15px;margin:0 0 8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;background:#f6f8fa;padding:12px;border-radius:6px;max-height:420px;overflow:auto}.muted{color:var(--muted)}#status{margin:15px 0;min-height:24px}details{margin-top:10px}summary{cursor:pointer;color:var(--accent)}.tag{display:inline-block;background:#e6f4ef;color:#176350;border-radius:4px;padding:2px 7px;margin:0 6px 8px 0;font-size:12px}.notice{background:#fff8e7;color:#77521b}.actions{display:flex;gap:8px;margin-top:10px}textarea{min-height:90px}#correction{margin-top:20px}@media(max-width:800px){.columns{grid-template-columns:1fr}}
</style></head><body><header><h1>Recanta <span class="muted">Inspector</span></h1><p>Trace current memory back to its evidence, decisions and corrections.</p></header><main>
<form id="search" class="toolbar"><div class="field"><label for="scope">Authorized scope</label><select id="scope"></select></div><div class="field" style="flex:3"><label for="query">Task or question</label><input id="query" value="What is my current budget?" required maxlength="4096"></div><button class="primary">Inspect context</button><button type="button" id="episodes">Find episode</button><button type="button" id="fresh">Check freshness</button></form>
<div id="status" role="status" aria-live="polite">Enter a question to inspect memory.</div>
<div class="columns"><section><div class="panel"><h2>Current memory</h2><div id="facts" class="muted">No query yet.</div></div><div class="panel"><h2>Evidence and processing</h2><div id="evidence" class="muted">Select an evidence reference to inspect source versions and decisions.</div></div></section><aside><div class="panel"><h2>Pipeline decisions</h2><div id="plan" class="muted">Candidate survival and budget decisions will appear here.</div></div><div class="panel"><h2>Coverage and unresolved state</h2><div id="gaps" class="muted">Processing readiness will appear here.</div></div><div class="panel"><h2>Sources and episodes</h2><div id="sources" class="muted">Original sources remain distinct from accepted memory.</div></div></aside></div>
<section id="correction" class="panel"><h2>Record a correction</h2><p id="actor" class="muted"></p><label for="message">Raw correction message</label><textarea id="message" placeholder="Actually, my budget is 60000 CNY."></textarea><div class="actions"><button id="save" class="primary" type="button">Retain correction and requery</button></div><p class="muted">The normal authority and ambiguity policy applies. A correction may remain unresolved.</p></section>
</main><script nonce="__NONCE__">
const token=__TOKEN__; let config; let inspection; const $=id=>document.getElementById(id);
async function api(route,payload){const r=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error+' ('+data.code+')');return data;}
function status(text){$('status').textContent=text;}
function block(title,data,parent){const d=document.createElement('details');const s=document.createElement('summary');s.textContent=title;const p=document.createElement('pre');p.textContent=JSON.stringify(data,null,2);d.append(s,p);parent.append(d);}
function evidenceButton(id,parent){const b=document.createElement('button');b.textContent='Inspect source';b.onclick=()=>run(async()=>{const data=await api('evidence',{evidenceId:id});$('evidence').replaceChildren();block(data.current?'Current source':'Historical source',data.evidence,$('evidence'));for(const r of data.runs){block('Processing: '+r.status,r,$('evidence'));if(['failed','requested','processing'].includes(r.status)&&config.canWrite){const retry=document.createElement('button');retry.textContent='Retry processing';retry.onclick=()=>run(async()=>{const result=await api('retry',{processingId:r.id});await inspect();status('Retry result: '+result.status);});$('evidence').append(retry);}}status('Evidence loaded.');});parent.append(b);}
async function inspect(){inspection=await api('inspect',{scopes:[$('scope').value],query:$('query').value,maxBytes:32768});$('facts').replaceChildren();for(const f of inspection.body.facts){const card=document.createElement('article');card.className='card';const title=document.createElement('h3');title.textContent=f.subjectId+' / '+f.predicate;const tag=document.createElement('span');tag.className='tag';tag.textContent=f.status;const value=document.createElement('pre');value.textContent=JSON.stringify(f.values,null,2);card.append(title,tag,value);block('Why selected and revision history',inspection.facts.find(x=>x.key.subjectId===f.subjectId&&x.key.predicate===f.predicate),card);for(const c of f.claims)for(const id of c.evidenceIds)evidenceButton(id,card);$('facts').append(card);}if(!inspection.body.facts.length)$('facts').textContent='No fact slots selected.';$('plan').replaceChildren();block('Retrieval and budget',{retrieval:inspection.plan.retrieval,budget:inspection.plan.budget},$('plan'));block('Candidate survival',inspection.plan.candidates,$('plan'));$('gaps').replaceChildren();block('Readiness',inspection.body.processing,$('gaps'));block('Processing gaps (diagnostic)',inspection.plan.processing.gaps,$('gaps'));for(const u of inspection.body.unresolved)block('Unresolved: '+u.decision.reason,u.decision,$('gaps'));$('sources').replaceChildren();for(const s of inspection.body.sources){block(s.factLinks.map(l=>l.relation).join(', ')||'Raw source',s,$('sources'));evidenceButton(s.citation.evidenceId,$('sources'));}for(const s of inspection.body.contextualEvidence)block('Episode context',s,$('sources'));status('Context: '+inspection.context.bytes+' bytes · '+(inspection.body.processing.ready?'processing ready':'processing gaps present'));}
async function run(fn){document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){status(e.message);}finally{document.querySelectorAll('button').forEach(b=>b.disabled=false);if(config&&!config.canWrite)$('save').disabled=true;}}
$('search').onsubmit=e=>{e.preventDefault();run(inspect);};$('fresh').onclick=()=>run(async()=>{if(!inspection)throw new Error('Inspect context first.');const r=await api('fresh',{snapshot:inspection.context.snapshot});status(r.fresh?'Context is fresh.':'Context is stale. Inspect again before using it.');});
$('episodes').onclick=()=>run(async()=>{const r=await api('episodes',{scopes:[$('scope').value],query:$('query').value,maxBytes:32768});const data=JSON.parse(r.text);$('sources').replaceChildren();for(const episode of data.episodes)block('Stream '+episode.streamId,episode,$('sources'));status(data.episodes.length+' episode neighborhoods · '+data.omittedEpisodes+' omitted for budget');});
$('save').onclick=()=>run(async()=>{if(!inspection)throw new Error('Inspect context before recording a correction.');const receipt=await api('correct',{scopeId:$('scope').value,content:$('message').value,snapshot:inspection.context.snapshot});await inspect();$('message').value='';status('Correction processing: '+receipt.readiness.memory);});
run(async()=>{config=await api('config',{});for(const scope of config.scopes){const o=document.createElement('option');o.value=scope;o.textContent=scope;$('scope').append(o);}$('actor').textContent=config.canWrite?'Corrections use the configured source identity: '+config.actorId:'This inspector is read only.';$('correction').hidden=!config.canWrite;});
</script></body></html>`;
